#!/usr/bin/env node
// Renders the app icon PNGs (same drawing as app/icons/icon.svg) with a tiny software rasterizer.
// Provenance: generated by this script from geometry only; no external image or model is involved.
import { deflateSync } from "node:zlib";
import { writeFileSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const OUT = join(dirname(fileURLToPath(import.meta.url)), "..", "app", "icons");
mkdirSync(OUT, { recursive: true });

const TEAL = [0x0e, 0x6a, 0x64];
const CREAM = [0xfb, 0xf4, 0xe4];

// geometry in the 512 design grid
const roundedRect = (x, y, w, h, r) => (px, py) => {
  const cx = Math.max(x + r, Math.min(px, x + w - r));
  const cy = Math.max(y + r, Math.min(py, y + h - r));
  return (px - cx) ** 2 + (py - cy) ** 2 <= r * r && px >= x && px <= x + w && py >= y && py <= y + h;
};
const triangle = (a, b, c) => (px, py) => {
  const s = (p, q, r) => (p[0] - r[0]) * (q[1] - r[1]) - (q[0] - r[0]) * (p[1] - r[1]);
  const p = [px, py];
  const d1 = s(p, a, b), d2 = s(p, b, c), d3 = s(p, c, a);
  return !((d1 < 0 || d2 < 0 || d3 < 0) && (d1 > 0 || d2 > 0 || d3 > 0));
};

const tabs = Array.from({ length: 7 }, (_, i) => ({ hit: roundedRect(96 + i * 47, 92, 38, 60, 10), alpha: i === 3 ? 1 : 0.5 }));
const page = roundedRect(96, 132, 320, 288, 28);
const play = triangle([215, 229], [215, 323], [297, 276]);

function pixel(x, y, rounded) {
  let c = null;
  if (rounded && !roundedRect(0, 0, 512, 512, 112)(x, y)) return [0, 0, 0, 0];
  c = [...TEAL, 1];
  const over = (rgb, a) => (c = [0, 1, 2].map((i) => c[i] * (1 - a) + rgb[i] * a).concat(1));
  for (const t of tabs) if (t.hit(x, y)) over(CREAM, t.alpha);
  if (page(x, y)) over(CREAM, 1);
  if (play(x, y)) over(TEAL, 1);
  return c;
}

function render(size, { rounded, inset = 0 }) {
  const SS = 3;
  const scale = 512 / (size * (1 - inset * 2));
  const off = (size * inset) * scale;
  const rows = [];
  for (let py = 0; py < size; py++) {
    const row = Buffer.alloc(1 + size * 4);
    for (let px = 0; px < size; px++) {
      let r = 0, g = 0, b = 0, a = 0;
      for (let sy = 0; sy < SS; sy++)
        for (let sx = 0; sx < SS; sx++) {
          const x = (px + (sx + 0.5) / SS) * scale - off;
          const y = (py + (sy + 0.5) / SS) * scale - off;
          const inside = x >= -0.001 && y >= -0.001 && x <= 512 && y <= 512;
          const p = inside ? pixel(x, y, rounded) : rounded ? [0, 0, 0, 0] : [...TEAL, 1];
          r += p[0] * p[3]; g += p[1] * p[3]; b += p[2] * p[3]; a += p[3];
        }
      const n = SS * SS;
      row[1 + px * 4] = a ? Math.round(r / a) : 0;
      row[2 + px * 4] = a ? Math.round(g / a) : 0;
      row[3 + px * 4] = a ? Math.round(b / a) : 0;
      row[4 + px * 4] = Math.round((a / n) * 255);
    }
    rows.push(row);
  }
  return Buffer.concat(rows);
}

const crcTable = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const byte of buf) c = crcTable[(c ^ byte) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
const chunk = (type, data) => {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
};

function png(size, opts) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // RGBA
  const meta = Buffer.from("Source\0Generated by scripts/make-icons.mjs from geometry only (no external image or model).");
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("tEXt", meta),
    chunk("IDAT", deflateSync(render(size, opts), { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

for (const [name, size, opts] of [
  ["icon-192.png", 192, { rounded: true }],
  ["icon-512.png", 512, { rounded: true }],
  ["icon-maskable-512.png", 512, { rounded: false, inset: 0.1 }],
]) {
  writeFileSync(join(OUT, name), png(size, opts));
  console.log("wrote", name);
}
